diff --git a/src/pcre2_substitute.c b/src/pcre2_substitute.c
--- a/src/pcre2_substitute.c
+++ b/src/pcre2_substitute.c
@@ -931,8 +931,8 @@ pcre2_substitute(const pcre2_code *code, PCRE2_SPTR subject, PCRE2_SIZE length,
            offsetof(pcre2_match_data, ovector) + 2 * pairs * sizeof(PCRE2_SIZE));
     internal_match_data->heapframes = NULL;
     internal_match_data->heapframes_size = 0;
-    /* Ensure that the subject is not freed when internal_match_data is */
-    internal_match_data->flags &= ~PCRE2_MD_COPIED_SUBJECT;
+    if (original_subject != match_data->subject)
+      internal_match_data->flags &= ~PCRE2_MD_COPIED_SUBJECT;
     match_data = internal_match_data;
   }

diff --git a/src/pcre2_match_data.c b/src/pcre2_match_data.c
--- a/src/pcre2_match_data.c
+++ b/src/pcre2_match_data.c
@@ -177,6 +177,9 @@ pcre2_get_startchar(pcre2_match_data *match_data)
 PCRE2_EXP_DEFN PCRE2_SPTR PCRE2_CALL_CONVENTION
 pcre2_get_subject(pcre2_match_data *match_data, PCRE2_SIZE *lengthptr)
 {
+  if (match_data == NULL)
+    return NULL;
+
   if (lengthptr != NULL)
     *lengthptr = match_data->subject_length;
   return match_data->subject;
